No library needed. Node's built-in `fs.createReadStream` + `readline` handle exactly this: constant memory usage, backpressure handled natively, zero dependencies. A 500MB file is trivial for a stream.

```js
import { createReadStream } from 'node:fs';
import { createInterface } from 'node:readline';
import { createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';

/**
 * Streams a log file line-by-line, yielding lines containing 'ERROR'.
 * Memory usage stays O(1) regardless of file size.
 */
async function* readErrorLines(filePath) {
  const rl = createInterface({
    input: createReadStream(filePath, { encoding: 'utf8' }),
    crlfDelay: Infinity, // handles \r\n correctly across chunk boundaries
  });

  for await (const line of rl) {
    if (line.includes('ERROR')) yield line;
  }
}

// Usage 1: process errors one at a time
for await (const err of readErrorLines('./app.log')) {
  console.error(err);
}

// Usage 2: stream matching lines to an output file without buffering
async function extractErrors(inputPath, outputPath) {
  const rl = createInterface({
    input: createReadStream(inputPath, { encoding: 'utf8' }),
    crlfDelay: Infinity,
  });

  const out = createWriteStream(outputPath, { encoding: 'utf8' });

  for await (const line of rl) {
    if (line.includes('ERROR')) {
      // write() returns false when the buffer is full — respect backpressure
      if (!out.write(line + '\n')) {
        await new Promise((resolve) => out.once('drain', resolve));
      }
    }
  }
  out.end();
  await new Promise((resolve, reject) => {
    out.on('finish', resolve);
    out.on('error', reject);
  });
}
```

Key points:

- **Memory**: only one line (plus the internal buffer, ~64KB) is in memory at a time. Peak RSS will be tens of MB, not 500MB.
- **`crlfDelay: Infinity`**: prevents `\r\n` sequences split across stream chunks from being mis-parsed as two line breaks.
- **Backpressure**: in Usage 2, if the write stream fills up, we pause the read loop until `drain` fires. The `readline` async iterator already pauses reads while your loop body is busy.
- **If all you need is extraction to a file**, the shell does this faster than any JS: `grep ERROR app.log > errors.log`. Native primitives first.

