```python
import urllib.request
import urllib.error
import socket


def fetch_urls(urls):
    """
    Download each URL with a 10-second timeout, retrying once on failure.

    Returns a dict mapping each URL to either its response body text
    or an error string describing what went wrong.
    """
    results = {}
    for url in urls:
        results[url] = _fetch_with_retry(url)
    return results


def _fetch_with_retry(url, attempts=2):
    """Try to fetch a URL, retrying once (2 attempts total) on failure."""
    last_error = None
    for attempt in range(attempts):
        try:
            return _fetch(url)
        except Exception as e:
            last_error = _describe_error(e)
    return last_error


def _fetch(url):
    """Fetch a single URL and return the decoded body text."""
    request = urllib.request.Request(
        url, headers={"User-Agent": "fetch-urls/1.0"}
    )
    with urllib.request.urlopen(request, timeout=10) as response:
        raw = response.read()
        # Use the charset from headers if present, else default to UTF-8
        charset = response.headers.get_content_charset() or "utf-8"
        return raw.decode(charset, errors="replace")


def _describe_error(e):
    """Turn an exception into a readable error string."""
    if isinstance(e, urllib.error.HTTPError):
        return f"Error: HTTP {e.code} {e.reason}"
    if isinstance(e, urllib.error.URLError):
        reason = e.reason
        if isinstance(reason, socket.timeout):
            return "Error: request timed out after 10s"
        return f"Error: {reason}"
    if isinstance(e, socket.timeout):
        return "Error: request timed out after 10s"
    return f"Error: {e}"


if __name__ == "__main__":
    urls = [
        "https://example.com",
        "https://httpbin.org/status/404",
        "https://this-domain-does-not-exist.invalid",
    ]
    for url, result in fetch_urls(urls).items():
        print(f"{url}\n  -> {result[:80]!r}\n")
```

A few design notes:

- **Timeout**: passed to `urlopen`, covering connection and read operations.
- **Retry**: `_fetch_with_retry` makes 2 attempts total (initial + one retry). It retries on any exception — if you'd rather not retry HTTP errors like 404 (retrying those is usually pointless), catch `HTTPError` separately and return immediately.
- **Decoding**: respects the `charset` parameter from the `Content-Type` header, falling back to UTF-8 with `errors="replace"` so a malformed body never crashes the function.
- **Sequential**: downloads happen one at a time. If you need concurrency, `concurrent.futures.ThreadPoolExecutor` is still standard library — happy to add that variant.

One caveat: `urlopen` follows redirects by default, so a URL that redirects will map to the *final* response body. If you need to detect or block redirects, that requires a custom `HTTPRedirectHandler`.

