### `src/infrastructure/formatters/csv-formatter.ts`
```typescript
import { Readable } from 'stream';
import { CustomerFormatter, FormattedOutput } from '../../application/formatter';
import { Customer } from '../../domain/customer';

type FieldDef = {
  key: keyof Customer;
  label: string;
  transform?: (c: Customer) => string;
};

export interface CsvFormatterOptions {
  includeHeader?: boolean;
  delimiter?: string;
  bom?: boolean;
  fields?: FieldDef[];
}

const DEFAULT_FIELDS: FieldDef[] = [
  { key: 'id', label: 'ID' },
  { key: 'email', label: 'Email' },
  { key: 'name', label: 'Name' },
  { key: 'tier', label: 'Tier' },
  { key: 'createdAt', label: 'Created At', transform: (c) => c.createdAt.toISOString() },
  { key: 'metadata', label: 'Metadata', transform: (c) => JSON.stringify(c.metadata ?? {}) },
];

export class CsvCustomerFormatter implements CustomerFormatter {
  readonly format = 'csv';
  readonly contentType = 'text/csv';
  readonly extension = 'csv';

  private readonly fields: FieldDef[];

  constructor(private readonly options: CsvFormatterOptions = {}) {
    this.fields = options.fields ?? DEFAULT_FIELDS;
  }

  serialize(customers: AsyncIterable<Customer>): FormattedOutput {
    const { includeHeader = true, delimiter = ',', bom = true } = this.options;
    let count = 0;
    const escape = (v: string) => this.escape(v);

    async function* generator() {
      if (bom) yield '\uFEFF';
      if (includeHeader) {
        yield DEFAULT_FIELDS.map((f) => escape(f.label)).join(delimiter) + '\n';
      }
      for await (const customer of customers) {
        count++;
        const row = DEFAULT_FIELDS.map((f) => {
          const raw = f.transform ? f.transform(customer) : String((customer as any)[f.key] ?? '');
          return escape(raw);
        }).join(delimiter);
        yield row + '\n';
      }
    }

    const stream = Readable.from(generator());

    const recordCount = new Promise<number>((resolve, reject) => {
      stream.on('end', () => resolve(count));
      stream.on('error', reject);
    });

    return { stream, contentType: this.contentType, extension: this.extension, recordCount };
  }

  private escape(value: string): string {
    if (value == null) return '';
    const str = String(value);
    if (str.includes(',') || str.includes('"') || str.includes('\n') || str.includes('\r')) {
      return '"' + str.replace(/"/g, '""') + '"';
    }
    return str;
  }
}
