```typescript
import { Transform } from 'stream';
import crypto from 'crypto';
import { DeliveryPipeline } from '../../application/pipeline';
import { FormattedOutput } from '../../application/formatter';
import { ExportConfig, ExportResult } from '../../domain/export';
import { LegacyReportingPipeline } from './legacy-reporting-pipeline';

export class ReportingPipelineAdapter implements DeliveryPipeline {
  constructor(
    private readonly legacy: LegacyReportingPipeline,
    private readonly jobId: string
  ) {}

  async deliver(output: FormattedOutput, config: ExportConfig): Promise<ExportResult> {
    const filename = `customer-export-${config.format}-${Date.now()}.${output.extension}`;
    const hash = crypto.createHash('sha256');

    // Tee the stream through a hasher so we can compute a checksum without buffering.
    const hasher = new Transform({
      transform(chunk: Buffer, _encoding, callback) {
        hash.update(chunk);
        callback(null, chunk);
      },
    });

    const uploadStream = output.stream.pipe(hasher);

    const { url, bytesUploaded } = await this.legacy.uploadStream(uploadStream, {
      filename,
      contentType: output.contentType,
    });

    await this.legacy.notifyComplete(this.jobId, {
      jobId: this.jobId,
      format: config.format,
      destination: url,
      bytesUploaded,
    });

    // By now the stream has been fully consumed, so recordCount is resolved.
    const recordCount = await output.recordCount;

    return {
      destination: url,
      recordCount,
      format: config.format,
      checksum: hash.digest('hex'),
    };
  }
}
