def fetch_urls(urls, timeout=10):
    """
    Download each HTTP/HTTPS URL with a 10-second timeout and one retry on failure.
    Returns a dict mapping URL -> response text or an error string.
    Uses only the Python standard library.
    """
    import urllib.request
    import urllib.error
    import socket

    results = {}

    headers = {
        "User-Agent": "Python-urllib",
        "Accept": "*/*",
        "Accept-Encoding": "identity",  # avoid compressed responses to keep decoding simple
        "Connection": "close",
    }

    def get_text_from_response(resp):
        data = resp.read()
        # Prefer charset from Content-Type; default to UTF-8 with replacement
        charset = None
        try:
            charset = resp.headers.get_content_charset()
        except Exception:
            charset = None
        if not charset:
            ct = resp.headers.get("Content-Type", "")
            for part in ct.split(";"):
                part = part.strip()
                if part.lower().startswith("charset="):
                    charset = part.split("=", 1)[1].strip()
                    break
        if not charset:
            charset = "utf-8"
        try:
            return data.decode(charset, errors="replace")
        except LookupError:
            # Unknown declared charset; fall back to UTF-8
            return data.decode("utf-8", errors="replace")

    for url in urls:
        if not isinstance(url, str):
            results[url] = "Invalid URL: not a string"
            continue
        if not url.lower().startswith(("http://", "https://")):
            results[url] = "Unsupported URL scheme (expected http or https)"
            continue

        last_error = None
        for _ in range(2):  # first try + one retry
            try:
                req = urllib.request.Request(url, headers=headers, method="GET")
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    results[url] = get_text_from_response(resp)
                    last_error = None
                    break
            except urllib.error.HTTPError as e:
                # Close the file pointer if any to avoid resource leaks
                try:
                    e.close()
                except Exception:
                    pass
                last_error = f"HTTPError {getattr(e, 'code', '')}: {getattr(e, 'reason', e)}"
            except urllib.error.URLError as e:
                reason = getattr(e, "reason", e)
                last_error = f"URLError: {reason}"
            except socket.timeout:
                last_error = "Timeout"
            except Exception as e:
                last_error = f"Error: {e}"

        if last_error is not None:
            results[url] = last_error

    return results
